def calculate_average(filtered_data, kwargs):
    if not filtered_data:
        return 0
    total_value = 0
    count = 0
    for record in filtered_data:
        value = record.get(kwargs['valueVar'])
        if value is not None:
            total_value += value
            count += 1
    return total_value / count if count > 0 else 0

def generalized_filter(data, kwargs):
    final_comparison = []

    for record in data:
        # Safely access the specified field inside each record
        field_value = record.get(kwargs['fieldVar'])
        if field_value is not None:
            # Convert field_value to integer for comparison
            try:
                field_value = int(field_value)
            except ValueError:
                continue

            # Append to final_comparison if field_value is greater than threshold
            if field_value > kwargs['thresholdVar']:
                final_comparison.append(record)

    return final_comparison

def process_dataset_with_compensation(data, kwargs):
    for record in data:
        salary = record.get(kwargs['salaryVar'], 0)
        bonus = record.get(kwargs['bonusVar'], 0)
        record[kwargs['newFieldVar']] = salary + bonus
    return data

def process_records(data, kwargs):
    result = {}
    for record in data:
        key_value = record.get(kwargs['groupFieldVar'])
        comparison_value = record.get(kwargs['comparisonFieldVar'], 0)

        # Ensure comparison_value is an integer for comparison
        comparison_value = int(comparison_value)

        if key_value not in result or comparison_value > result[key_value].get(kwargs['comparisonFieldVar'], 0):
            result[key_value] = record

    return list(result.values())

