def calculate_correlation(data, kwargs):
    import numpy as np

    x_values = []
    y_values = []

    for entry in data:
        try:
            x_value = entry.get(kwargs['xFieldVar'])
            y_value = entry.get(kwargs['yFieldVar'])
            if x_value is not None and y_value is not None:
                x_values.append(float(x_value))
                y_values.append(float(y_value))
        except ValueError:
            continue

    if len(x_values) > 1 and len(y_values) > 1:
        correlation = np.corrcoef(x_values, y_values)[0, 1]
    else:
        correlation = None

    return {kwargs['outputVar']: correlation}

